package com.habilitesrandom;
import com.habilitesrandom.api.*;import com.habilitesrandom.api.event.*;import com.habilitesrandom.api.execution.*;import com.habilitesrandom.registry.*;import net.minecraft.resources.Identifier;import org.junit.jupiter.api.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import static org.junit.jupiter.api.Assertions.*;
class PlusApiTest {
 @Test void externalGraphRegistersAndAutomaticallyQueries(){var c=new ContentCatalog();var r=new DefaultContentRegistrar(c,"test_plus",1);Identifier anime=id("anime"),rarity=id("rare"),form=id("form");assertTrue(r.registerAnime(new AnimeDefinition(anime,"Anime","")));assertTrue(r.registerRarity(new RarityDefinition(rarity,"Rare",0xff00aaff,10,1)));var ids=List.of(id("a1"),id("a2"),id("a3"),id("a4"));for(var id:ids)assertTrue(r.registerAbility(AbilityDefinition.builder(id).displayName(id.toString()).cooldownTicks(20).damage(1).range(2).types(AbilityType.MELEE).build()));assertTrue(r.registerTransformation(TransformationDefinition.builder(form).displayName("Form").durationTicks(100).build()));var character=CharacterDefinition.builder(id("hero")).displayName("Hero").anime(anime).rarity(rarity).category(StrengthCategory.STRONG).weight(7).abilities(ids.get(0),ids.get(1),ids.get(2),ids.get(3)).powerfulForm(form).build();assertTrue(r.registerCharacter(character));CatalogValidator.validate(c);assertEquals(character,new CharacterRegistry(c).get(character.id()).orElseThrow());assertEquals(7,new CharacterRegistry(c).totalWeight());}
 @Test void invalidAndDuplicateRegistrationsAreIsolated(){var c=new ContentCatalog();var r=new DefaultContentRegistrar(c,"broken_plus",1);var anime=new AnimeDefinition(id("same"),"One","");assertTrue(r.registerAnime(anime));assertFalse(r.registerAnime(new AnimeDefinition(id("same"),"Two","")));var missing=CharacterDefinition.builder(id("broken")).displayName("Broken").anime(id("missing")).rarity(id("missing")).category(StrengthCategory.WEAK).weight(1).abilities(id("1"),id("2"),id("3"),id("4")).powerfulForm(id("none")).build();assertFalse(r.registerCharacter(missing));}
 @Test void eventsCanBeObservedAndUnregistered() throws Exception {var count=new AtomicInteger();AutoCloseable registration=HabilitesRandomEvents.ABILITY_USED.register(event->count.incrementAndGet());assertEquals(1,HabilitesRandomEvents.ABILITY_USED.listenerCount());registration.close();assertEquals(0,HabilitesRandomEvents.ABILITY_USED.listenerCount());}
 @Test void apiVersionContractIsExplicit(){assertTrue(com.habilitesrandom.core.CoreServices.supports(1));assertFalse(com.habilitesrandom.core.CoreServices.supports(2));}
 private static Identifier id(String path){return Identifier.fromNamespaceAndPath("test_plus",path);}
}
